SELECT monthly_fee_bucket, total_monthly_fee FROM (SELECT CASE WHEN monthly_fee >= 195 THEN 'high' WHEN monthly_fee >= 37 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, SUM(monthly_fee) AS total_monthly_fee FROM subscriptions WHERE status = 'ACTIVE' GROUP BY CASE WHEN monthly_fee >= 195 THEN 'high' WHEN monthly_fee >= 37 THEN 'mid' ELSE 'low' END) AS sub WHERE total_monthly_fee > 1170 ORDER BY monthly_fee_bucket DESC;
